void invertir(char *str, int inicio, int fin) {
    if (inicio >= fin) return;
    char temp = str[inicio];
    str[inicio] = str[fin];
    str[fin] = temp;
    invertir(str, inicio + 1, fin - 1);
}
```

```c
void invertir_cadena(char *str) {
    invertir(str, 0, strlen(str) - 1);
}
